+		// A node reference call resolves the node's run data on every call, and
+		// all() returns every item, so a body calling it per element is charged
+		// for the items each call returns.
+		test('node reference calls in a callback body are charged per visit', () => {
+			const rows = new Array<number>(100_000).fill(0);
+			let calls = 0;
+			const $ = () => ({
+				all: () => {
+					calls++;
+					return rows;
+				},
+			});
+			const visits = Math.floor(MAX_WORK / (rows.length + 1));
+			const expr = "{{ $json.many.some(n => $('Source').all().length < n) }}";
+
+			expect(
+				nativeOn(expr, { $, $json: { many: new Array<number>(visits + 1).fill(0) } }),
+			).toEqual({ handled: false });
+			expect(calls).toBeLessThanOrEqual(visits + 1);
+
+			expect(nativeOn(expr, { $, $json: { many: new Array<number>(10).fill(0) } })).toEqual({
+				handled: true,
+				value: false,
+			});
+		});
